import{z as s,x as n,o as e,c as o,q as t,j as P,D as a,d as l,s as A,S as i,b as B}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"DP/PP/TP/EP 深入对照","description":"","frontmatter":{"title":"DP/PP/TP/EP 深入对照","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dist-parallel-deep-comparison.md","filePath":"llm/dist-parallel-deep-comparison.md","lastUpdated":1791413859000}'),p={name:"llm/dist-parallel-deep-comparison.md"};function d(D,E,m,h,T,c){const r=n("Mermaid");return e(),o("div",null,[E[2]||(E[2]=t('<h1 id="dp-pp-tp-ep-深入对照" tabindex="-1">DP/PP/TP/EP 深入对照 <a class="header-anchor" href="#dp-pp-tp-ep-深入对照" aria-label="Permalink to &quot;DP/PP/TP/EP 深入对照&quot;">​</a></h1><div class="epigraph"><p>四种并行不是四个开关，而是切四种不同状态的轴：批、层深、矩阵宽、专家路由；对照的意义是看清每一轴每步在搬什么字节。</p><footer>—— 据 Shoeybi 等 2019 与 Narayanan 等 2021 整理</footer></div><p><a href="/llm/ti-map">上一课</a>把训练基础设施收成九步决策单与三条不变量：轨迹契约、指纹唯一、账随时可查，管的是 step 骨架与账本。骨架立好之后，算力超出单机：状态怎么切、每步付什么字节、谁在等谁、坏了丢多少，是本课程的问题。本课程是「分布式训练深入」的第一课。主干课分别写过<a href="/llm/data-parallel-zero">数据并行与 ZeRO</a>、<a href="/llm/tensor-parallel">张量并行</a>、<a href="/llm/pipeline-parallel">流水线并行</a>与 <a href="/llm/expert-parallelism">Expert Parallelism</a>；本课不再逐个入门，而是把四轴放进同一张对照表：切什么状态、每步交换什么、落在哪条链路、坏了是什么症状。后课默认已经读完这张表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>选并行配置时缺的不是各轴的知识，而是同一坐标系里的读法。每份框架文档都会提醒 TP 度别超过 8、PP 别太深；真正决定配置的是四轴在五列上的取值：状态切分、通信原语、通信体积、链路亲和、失败症状。四轴几乎总是混用，还必须知道哪些列相加、哪些列取 max。没有这张表，配置讨论会退化成口号：「MoE 用 EP」「大模型加 TP」，而不知道代价落在哪一列。</p><p><span class="marginnote">一个直觉读法：DP 是「每人做不同的题，考前对答案」，TP 是「一道题拆给几个人合算」，PP 是「流水线，每人负责几道工序」，EP 是「不同题型分给不同的专家组」。切的东西不同，每步付的通信费也不同。</span></p><h3 id="五列对照" tabindex="-1">五列对照 <a class="header-anchor" href="#五列对照" aria-label="Permalink to &quot;五列对照&quot;">​</a></h3><p>DP 切数据：参数、梯度、优化器状态全复制，每步一次 All-Reduce 族交换，体积与参数量同阶；消息大、频率低，能容忍跨节点，重叠之后多落在带宽区。症状是 step 均匀变长，没有局部热点。TP 切单层矩阵宽：每层正反向各一次 All-Reduce 量级，体积 \\(\\propto bsd\\) 乘层数，高频短消息，延迟敏感，必须待在 NVLink 域；症状是跨节点后层内等待把利用率拖垮。PP 切层深：阶段间点对点递激活，体积 \\(\\propto bsh\\)，频率按段；怕气泡与阶段不均，症状是稳定段之间的空拍与周期性 flush。EP 切专家路由：两次 All-to-All 是置换，没有可聚合的中间结果，跨节点最难层次化；症状是热专家既是计算热点又是网络热点。</p><p><span class="marginnote">四轴的缩放极限不同：TP 受头数整除与 NVLink 域大小限制，PP 受层数与气泡限制，EP 受专家数限制，DP 受全局 batch 与学习率语义限制。配置搜索先撞到的那个极限，就是该换轴的信号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把对照表用成约束满足问题：先按模型形状排除不可行项（头数除不尽、层太浅、专家数不够），再按「通信频率乘体积」把各轴排进链路层级——TP 进内圈 NVLink 域，DP 与 PP 放外圈跨节点，EP 看路由方案。然后用体积公式粗算每轴的通信账：DP 每步 \\(O(\\Phi)\\)，TP 每层 \\(O(bsd)\\)，PP 每段 \\(O(bsh)\\)，EP 每层两次置换 \\(O(bsdk)\\) 量级。哪一轴的账最贵，优化就从哪一轴开始；其余轴的开销用重叠与放置去遮。</p><p><span class="marginnote">代个数字感受 TP 的量级：\\(b=4\\)、\\(s=4096\\)、\\(d=4096\\) 时，每层一次 All-Reduce 的消息约 \\(b \\times s \\times d \\approx 6700\\) 万个数，fp16 下一百多 MB。一层一次、几十层高频发生——这就是 TP 必须待在 NVLink 域的原因。</span></p>',12)),(e(),P(i,null,{default:a(()=>[A(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20MODEL%5B%22%E6%A8%A1%E5%9E%8B%E4%B8%8E%E9%9B%86%E7%BE%A4%E5%BD%A2%E7%8A%B6%22%5D%20--%3E%20FEAS%5B%22%E6%95%B4%E9%99%A4%E4%B8%8E%E5%AE%B9%E9%87%8F%E5%8F%AF%E8%A1%8C%E6%80%A7%E8%BF%87%E6%BB%A4%22%5D%0A%20%20FEAS%20--%3E%20COST%5B%22%E5%9B%9B%E8%BD%B4%E9%80%9A%E4%BF%A1%E8%B4%A6%3A%20DP%20%E6%AF%8F%E6%AD%A5%20%2F%20TP%20%E6%AF%8F%E5%B1%82%20%2F%20PP%20%E6%AF%8F%E6%AE%B5%20%2F%20EP%20%E7%BD%AE%E6%8D%A2%22%5D%0A%20%20COST%20--%3E%20PLACE%5B%22%E9%93%BE%E8%B7%AF%E4%BA%B2%E5%92%8C%3A%20TP%20%E5%86%85%E5%9C%88%2C%20DP%20%E4%B8%8E%20PP%20%E5%A4%96%E5%9C%88%22%5D%0A%20%20PLACE%20--%3E%20TUNE%5B%22%E9%87%8D%E5%8F%A0%E4%B8%8E%E6%94%BE%E7%BD%AE%E6%94%B6%E5%B0%BE%2C%20%E6%9C%80%E8%B4%B5%E8%BD%B4%E5%85%88%E4%BC%98%E5%8C%96%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[l("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,"四轴能正交，因为各自的进程组独立，组内同步语义不外溢到别的组。同一维内部也有极限：TP 度增大时每层 All-Reduce 的参与者变多，NVLink 域装不下就退化；PP 度增大时气泡先被更多微批摊薄，再受 flush 与阶段负载不均制约；EP 度超过专家数就没有意义；DP 度增大最终撞全局 batch——学习率与批次语义随它一起变。所以「加深一维」不是免费的扩展：每维有自己的饱和曲线，配置是在四条曲线上找交点，而不是每维都拉满。",-1)),(e(),P(i,null,{default:a(()=>[A(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20INC%5B%22%E5%8A%A0%E6%B7%B1%E6%9F%90%E4%B8%80%E7%BB%B4%22%5D%20--%3E%20Q%7B%22%E5%85%88%E6%92%9E%E5%93%AA%E6%9D%A1%E9%A5%B1%E5%92%8C%E6%9B%B2%E7%BA%BF%3F%22%7D%0A%20%20Q%20--%3E%7C%E5%8A%A0%E6%B7%B1%20TP%7C%20TPD%5B%22%E5%8F%82%E4%B8%8E%E8%80%85%E8%B6%85%E5%87%BA%20NVLink%20%E5%9F%9F%2C%20%E5%B1%82%E5%86%85%E7%AD%89%E5%BE%85%E6%9A%B4%E6%B6%A8%22%5D%0A%20%20Q%20--%3E%7C%E5%8A%A0%E6%B7%B1%20PP%7C%20PPD%5B%22%E6%B0%94%E6%B3%A1%E6%91%8A%E8%96%84%E5%88%B0%E5%A4%B4%2C%20%E6%92%9E%20flush%20%E4%B8%8E%E9%98%B6%E6%AE%B5%E4%B8%8D%E5%9D%87%22%5D%0A%20%20Q%20--%3E%7C%E5%8A%A0%E6%B7%B1%20EP%7C%20EPD%5B%22%E5%BA%A6%E6%95%B0%E8%B6%85%E8%BF%87%E4%B8%93%E5%AE%B6%E6%95%B0%2C%20%E5%86%8D%E5%A4%A7%E6%97%A0%E6%84%8F%E4%B9%89%22%5D%0A%20%20Q%20--%3E%7C%E5%8A%A0%E6%B7%B1%20DP%7C%20DPD%5B%22%E6%92%9E%E5%85%A8%E5%B1%80%20batch%2C%20%E5%AD%A6%E4%B9%A0%E7%8E%87%E8%AF%AD%E4%B9%89%E4%B8%80%E8%B5%B7%E5%8F%98%22%5D%0A%20%20TPD%20--%3E%20RES%5B%22%E9%85%8D%E7%BD%AE%20%3D%20%E5%9B%9B%E6%9D%A1%E6%9B%B2%E7%BA%BF%E4%B8%8A%E6%89%BE%E4%BA%A4%E7%82%B9%2C%20%E4%B8%8D%E6%98%AF%E6%AF%8F%E7%BB%B4%E6%8B%89%E6%BB%A1%22%5D%0A%20%20PPD%20--%3E%20RES%0A%20%20EPD%20--%3E%20RES%0A%20%20DPD%20--%3E%20RES%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">初学者容易以为「并行度越大越快」。实际上比如 PP 加深一倍，气泡未必变小，阶段负载不均反而更难调。正确的问法不是「这一维加不加」，而是「当前先爆的那块状态，归哪根轴管」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课给对照与读法，不给组合算法：多维组合的进程组细节见 <a href="/llm/nd-parallel">3D / 5D 并行组合</a>；逻辑组到物理链路的映射是后课的事；DP 轴那块「全复制」的冗余怎么切，是下一课的主题。序列维是第五轴，<a href="/llm/context-parallel">序列并行 / 上下文并行</a>已单独立课，不在此展开。判断「该不该上某一维」的口诀：看该维切的状态是不是当前先爆的那一块——爆激活的模型加深 TP 帮助有限，要等后课的激活账。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四轴分别切数据、层深、矩阵宽、专家路由；进程组正交，通信账不同阶。</li><li>读配置用五列：状态、原语、体积、链路亲和、失败症状；TP 延迟敏感住 NVLink 域，EP 的置换最难层次化。</li><li>每轴有缩放极限与饱和曲线；先撞到的极限就是换轴信号。</li><li>最贵的通信账先优化，其余用重叠与放置遮；组合与映射归后课。</li><li>出处：Shoeybi 等，Megatron-LM，2019；Narayanan 等，Efficient Large-Scale Language Model Training on GPU Clusters Using Megatron-LM，2021。</li></ul>',5))])}const u=s(p,[["render",d]]);export{C as __pageData,u as default};
